-- GROUP 10: EDSA TRAFFIC MONITORING
-- REGENERATED REALISTIC SIMULATED TEACHING DATASET
-- Database: G10_edsatraffic. Target assumption: MySQL 8.0.16+ / InnoDB.
-- Actual data year: 2025-01-01 through 2025-12-31, with an exclusive midnight
-- end boundary for the last interval. Snapshot of current states at year end.
-- All counting locations, barangay mappings, manufacturers, equipment readings,
-- staff names, vehicle volumes and operational events are simulated.
-- They are NOT observed EDSA measurements, official classifications, verified
-- administrative geography, deployed-device specifications or actual restrictions.
-- Names may coincide with real entities without identifying those entities.
-- Statistical realism does not establish measured accuracy or authentic provenance.
-- No individual vehicles, plate numbers, driver identities or passage records.
-- This file must not be represented as official or empirically collected data.
--
-- Schema preserved: point/device/countperiod/vehcount/radarcal, 43 columns.
-- Version 4.0 rules: no CHECK clauses or standalone KEY/INDEX declarations.
-- Retain PRIMARY KEY, FOREIGN KEY, UNIQUE, ENUM, NOT NULL and defaults.
-- No lookup/subtype tables, reporting structures, triggers or routine workarounds.
-- No explicit character-set declarations. Student restructuring remains open.
--
-- ONE YEAR OF SCHEDULED SURVEYS, NOT FABRICATED CONTINUOUS 24-HOUR COVERAGE:
-- Four operating points, both directions, daily windows 06:00-08:00,
-- 11:00-13:00 and 16:00-18:00. These total six surveyed hours/day.
-- Acquisition gaps form short contiguous outages or missing survey blocks.
-- Missing periods are absent, not invented zero totals. Draft worksheets may
-- lack categories or await reconciliation. Reports use only Completed periods.
-- PT005 is reserved/inactive and has no counting activity.
-- Two additional PT001 manual intervals demonstrate year-boundary selection.
-- Explicit all-zero intervals represent a simulated temporary boundary closure.
-- Traffic volumes vary with weekday/weekend, time window, location, direction,
-- correlated adjacent intervals and common day-level conditions. Classes vary
-- together around a total rather than being independent unrelated numbers.
-- These patterns are illustrative; no real weather/event/policy effect is claimed.
--
-- DEVICE CONTEXT: DV001-DV008 normally cover separate point/direction slots.
-- DV009 substitutes for DV002 on 1-12 August and is retired by the snapshot;
-- current inactivity does not rewrite historical valid attribution.
-- DV010 is a spare Radar with calibration history and no count periods.
-- DV008 is suspended after Failed verification on 17 September. Manual totals
-- replace its use through 2 October. Authorized return occurs on 3 October,
-- following verification, not automatically from recording an outcome.
-- Current activation is not a full effective-dated deployment/eligibility history.
-- The application stores entered/imported aggregates; no sensor integration.
--
-- Car includes passenger cars/taxis/SUVs/passenger vans; Motorcycle two-wheel
-- motor vehicles; Bus guide-defined buses/minibuses; Jeepney traditional/modern
-- jeepneys; Truck pickups/cargo vans/goods vehicles. Other is outside those
-- definitions or unresolved class where the passage total is established.
-- Categories are exclusive. No unique corridor vehicle or journey count is implied.
-- A crossing at two points contributes twice; count volume alone does not prove
-- congestion, speed, travel time, road capacity or device recognition accuracy.
--
-- Fresh creation only, NOT migration. No DROP. Stop on first error; no --force.
-- Existing tables cause errors. DDL is not transactional; seed INSERTs are.
-- This is a replacement generated dataset, not a byte-preserving edit of an old
-- seed file. It retains the approved schema and report meanings.

SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
CREATE DATABASE IF NOT EXISTS G10_edsatraffic;
USE G10_edsatraffic;

CREATE TABLE `point` (
 pointno VARCHAR(12) NOT NULL PRIMARY KEY,
 pointnam VARCHAR(100) NOT NULL,
 brgycode VARCHAR(8) NOT NULL,
 brgyname VARCHAR(80) NOT NULL,
 landmark VARCHAR(180) NOT NULL,
 coverage VARCHAR(255) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1,
 revno INT UNSIGNED NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE `device` (
 devno VARCHAR(12) NOT NULL PRIMARY KEY,
 serialno VARCHAR(40) NOT NULL,
 mfrcode VARCHAR(8) NOT NULL,
 mfrname VARCHAR(100) NOT NULL,
 devtype ENUM('Camera','Radar') NOT NULL,
 resmp DECIMAL(6,2) NULL,
 nightmod ENUM('None','LowLight','Infrared') NULL,
 freqghz DECIMAL(8,3) NULL,
 rangem DECIMAL(8,2) NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 CONSTRAINT uq_manufacturer_serial UNIQUE (mfrcode,serialno)
) ENGINE=InnoDB;

CREATE TABLE `countperiod` (
 periodno VARCHAR(16) NOT NULL PRIMARY KEY,
 pointno VARCHAR(12) NOT NULL,
 directn ENUM('Northbound','Southbound') NOT NULL,
 startat DATETIME NOT NULL,
 endat DATETIME NOT NULL,
 method ENUM('Manual','Device') NOT NULL,
 devno VARCHAR(12) NULL,
 status ENUM('Draft','Completed') NOT NULL DEFAULT 'Draft',
 notes VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 CONSTRAINT uq_point_direction_start UNIQUE (pointno,directn,startat),
 FOREIGN KEY (pointno) REFERENCES point(pointno) ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY (devno) REFERENCES device(devno) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `vehcount` (
 periodno VARCHAR(16) NOT NULL,
 vehclass ENUM('Car','Motorcycle','Bus','Jeepney','Truck','Other') NOT NULL,
 vehicles INT UNSIGNED NOT NULL,
 notes VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 PRIMARY KEY (periodno,vehclass),
 FOREIGN KEY (periodno) REFERENCES countperiod(periodno) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `radarcal` (
 calno VARCHAR(16) NOT NULL PRIMARY KEY,
 devno VARCHAR(12) NOT NULL,
 caldate DATE NOT NULL,
 refdist DECIMAL(8,2) NOT NULL,
 reading DECIMAL(8,2) NOT NULL,
 result ENUM('Passed','Adjusted','Failed') NOT NULL,
 calby VARCHAR(100) NOT NULL,
 notes VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (devno) REFERENCES device(devno) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

-- AUTHORITATIVE APPLICATION RULES (not all enforced by DDL):
-- Nonblank required text, active 0/1, revno>=1. Keep current barangay and
-- manufacturer descriptions consistent per code. Preserve point coverage meaning.
-- Camera requires positive resmp/nightmod and NULL Radar attributes. Radar
-- requires positive freqghz/rangem and NULL Camera attributes.
-- Periods align to quarter hours, have exclusive end=start+15 minutes, and actual
-- end<=business time. Prevent overlapping point/direction periods and conflicting
-- device use at different points. Manual has no devno; Device requires eligible
-- device. Current inactivation does not invalidate earlier legitimate use.
-- Completed requires ALL six categories, each nonnegative, exactly once. Zero is
-- explicit; a missing category/period is missing information, not zero.
-- Parent-period coordination must prevent simultaneous completion and count edit.
-- Reopen before correction and revalidate before completing. Do not double-count
-- a manual replacement and the earlier device total as separate periods.
-- Radar-only calibration requires actual date, positive reference distance,
-- nonnegative reading, responsible technician and explained Adjusted/Failed.
-- No invented universal tolerance determines a technical outcome.
-- Failed verification and inactivation save together. Reactivation needs explicit
-- authorization. Calibration corrections do not automatically recalculate counts.
-- Protect identity/type/history; compare revno, increment after success, reject
-- stale saves, and confirm permitted erroneous-record deletions.
-- Authorization is external; no account/audit/history subsystem is assumed.
-- Required reports use current Completed status and current register labels.
-- Do not inflate period counts through six category rows or independent joins.

START TRANSACTION;

-- point: 5 simulated records.

-- device: 10 simulated records.

-- countperiod: 69852 simulated records.

-- vehcount: 418438 simulated records.

-- radarcal: 21 simulated records.

COMMIT;

